import { Component } from '@angular/core';

@Component({
  selector: 'app-ngo',
  templateUrl: './ngo.component.html',
  styleUrls: ['./ngo.component.css']
})
export class NgoComponent {
  ngos: any[] = [];
  filteredNGOs: any[] = [];

  searchText: string = '';
  selectedCategory: string = '';

  categories: string[] = [
    'Education',
    'Healthcare',
    'Environment',
    'Women Empowerment',
    'Child Welfare'
  ];

  constructor(private ngoService: NgoService) {}

  ngOnInit(): void {
    this.loadNGOs();
  }

  loadNGOs(): void {
    this.ngoService.getNGOs().subscribe({
      next: (data) => {
        this.ngos = data;
        this.filteredNGOs = data;
      },
      error: (error) => {
        console.error('Error loading NGOs:', error);
      }
    });
  }

  filterNGOs(): void {
    this.filteredNGOs = this.ngos.filter(ngo => {

      const matchesSearch =
        ngo.name.toLowerCase().includes(this.searchText.toLowerCase()) ||
        ngo.description.toLowerCase().includes(this.searchText.toLowerCase());

      const matchesCategory =
        !this.selectedCategory ||
        ngo.category === this.selectedCategory;

      return matchesSearch && matchesCategory;
    });
  }

  onSearch(): void {
    this.filterNGOs();
  }

  onCategoryChange(): void {
    this.filterNGOs();
  }

}
